// The shared vocabulary: written by the workflow from vocab/ (base constants + helper shares)
export * from "./vocab/base.mjs";
export * from "./vocab/h1.mjs";
export * from "./vocab/h2.mjs";
export * from "./vocab/h3.mjs";
export * from "./vocab/h4.mjs";
