// Rows along +z (z=22,23,24), columns along +x (x=23..30).
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { wardrobe, hung_lantern } from "../vocab.mjs";

const legend = {
